const payload = $json.body || $json;

const template = payload.template;
const recipient = payload.recipient || {};
const data = payload.data || {};

let subject = 'VivaSpot Notification';
let html = '<p>You have a new VivaSpot notification.</p>';

if (template === 'event_rsvp_confirmation') {
  subject = `You're confirmed for ${data.event?.name || 'your event'}`;
  html = `
    <h2>You're in!</h2>
    <p>Hi ${recipient.name || 'there'},</p>
    <p>Your RSVP is confirmed for <strong>${data.event?.name || 'the event'}</strong>.</p>
    <p><strong>When:</strong> ${data.event?.startDatetime || ''}</p>
    <p><strong>Where:</strong> ${data.event?.location || ''}</p>
    <p><strong>Tickets:</strong> ${data.order?.quantity || 1}</p>
    ${data.eventUrl ? `<p><a href="${data.eventUrl}">View event</a></p>` : ''}
    ${data.cancellationUrl ? `<p><a href="${data.cancellationUrl}">Cancel RSVP</a></p>` : ''}
  `;
}

if (template === 'event_rsvp_cancelled') {
  subject = `RSVP cancelled for ${data.event?.name || 'your event'}`;
  html = `
    <h2>RSVP Cancelled</h2>
    <p>Hi ${recipient.name || 'there'},</p>
    <p>Your RSVP for <strong>${data.event?.name || 'the event'}</strong> has been cancelled.</p>
    ${data.refund ? `<p>Refund status: ${data.refund.status}. Amount: $${((data.refund.amountCents || 0) / 100).toFixed(2)}</p>` : ''}
  `;
}

return [{
  json: {
    template,
    eventType: payload.eventType,
    to: recipient.email,
    recipientName: recipient.name,
    subject,
    html,
    payload
  }
}];
